document.addEventListener('DOMContentLoaded', function () {
    
    globalThis.borderOverlay = document.querySelector('.border-overlay');
    globalThis.container = document.getElementById('real-container');
    updateOverlaySize();
    // prgb =  RGBParse(getComputedStyle(document.body).backgroundColor);
    primary = getComputedStyle(document.body).backgroundColor
    svgflood = document.getElementById("svgflood");
    svgflood.setAttribute("flood-color", primary);
    
    svgstyle = document.styleSheets[1];
    svgstyle.insertRule(`.cls-1,.cls-2,.cls-3,.cls-4,.cls-5{stroke:${primary}; stroke-width: 3px;}`, svgstyle.cssRules.length);
    svgstyle.insertRule(` .cls-2,.cls-6{fill:${primary}}`, svgstyle.cssRules.length);
});

let debounce = false;



function updateOverlaySize() {
    o = globalThis.borderOverlay;
    c = globalThis.container;
    o.style.left = `calc(${getComputedStyle(c).marginLeft} - var(--border-size) / 2)`;
    o.style.width = `calc(${getComputedStyle(c).width} + var(--border-size))`;

}

window.addEventListener('resize', function () {
    if (!debounce) {
        updateOverlaySize()

    }
    debounce = true;
    setTimeout(function () { debounce = false; }, 50);
});